using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long n, a, b, c;
    if (!(cin >> n >> a >> b >> c)) return 0;

    long long liters = 0;

    if (b - c < a && n >= b) {
        long long i = (n - b) / (b - c) + 1;
        liters += i;
        n -= i * (b - c);
    }

    liters += n / a;

    cout << liters << '\n';

    return 0;
}

